type Bit is Data:
  BitZero{}
  BitOne{}

type Bool is Data:
  False{}
  True{}

type Box is Data:
  Box{value: Bit}

type Result is Data:
  Result{value: Bit}

type BoolResult is Data:
  BoolResult{value: Bool}

type Pair is Data:
  Pair{left: Bit, right: Bit}

type Choice is Data:
  First{inner: Bit, value: Bit}
  Second{value: Bit}
  Third{value: Bit}
  Fourth{value: Bit}

def zero() -> Bit:
  BitZero{}

def one() -> Bit:
  BitOne{}

def box(value: Bit) -> Box:
  Box{value}

def project(b: Box) -> Bit:
  match b:
    case Box{value}:
      value

def project_result(b: Box) -> Result:
  Result{project(b)}

def select(a: Bool, b: Bool) -> Bool:
  match a:
    case False{}:
      False{}
    case True{}:
      b

def bool_result(a: Bool, b: Bool) -> BoolResult:
  BoolResult{select(a, b)}

def first(inner: Bit, value: Bit) -> Choice:
  First{inner, value}

def second(value: Bit) -> Choice:
  Second{value}

def third(value: Bit) -> Choice:
  Third{value}

def fourth(value: Bit) -> Choice:
  Fourth{value}

def grouped(c: Choice, fallback: Bit) -> Bit:
  match c:
    case First{BitOne{}, value}:
      value
    case Second{value}:
      value
    case Third{value}:
      value
    case Fourth{value}:
      value
    case First{BitZero{}, value}:
      fallback

def grouped_result(c: Choice, fallback: Bit) -> Result:
  Result{grouped(c, fallback)}

def chain(a: Box, b: Box) -> Pair:
  x = project(a)
  y = project(b)
  Pair{x, y}

def callback_after(b: Box, f: Bit -> Bit) -> Result:
  x = project(b)
  Result{f(x)}

